 /// 主键\n  id       BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 通知 id\n  noticeId BigInt   @map(\"notice_id\") @db.BigInt\n  /// 客户端用户 id\n  userId   BigInt   @map(\"user_id\") @db.BigInt\n  /// 阅读时间\n  readAt   DateTime @default(now()) @map(\"read_at\")\n\n  notice ClientNotice @relation(fields: [noticeId], references: [id], onDelete: Cascade)\n\n  /// 同一人同一条只记一次（标记已读天然幂等）\n  @@unique([noticeId, userId])\n  /// 「我读过的」按时间倒序查\n  @@index([userId, readAt])\n  @@map(\"client_notice_read\")\n}\n\n// use prisma-next\n// ↑ 首行不可删：VS Code 的 Prisma 扩展**按文件**判定是否启用 Prisma 7 语言服务，\n//   缺失会回落到 v6 语义并误报 `Argument \"url\" is missing in data source block \"db\"`。\n//\n// 字典与系统参数\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n/// 字典类型表\nmodel DictType {\n  /// 主键\n  id        BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 字典名称（展示用）\n  dictName  String   @map(\"dict_name\") @db.VarChar(100)\n  /// 字典类型编码（业务引用键，创建后不可修改）\n  dictType  String   @unique @map(\"dict_type\") @db.VarChar(100)\n  /// 1 启用 / 0 禁用\n  status    Int      @default(1) @db.TinyInt\n  /// 备注\n  remark    String?  @db.VarChar(255)\n  /// 创建时间\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  items DictItem[]\n\n  @@map(\"sys_dict_type\")\n}\n\n/// 字典项表（通过 dict_type 字符串关联类型编码，删除类型时级联）\nmodel DictItem {\n  /// 主键\n  id        BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 所属字典类型编码\n  dictType  String   @map(\"dict_type\") @db.VarChar(100)\n  /// 字典标签（展示文案）\n  dictLabel String   @map(\"dict_label\") @db.VarChar(100)\n  /// 字典值（业务存储值）\n  dictValue String   @map(\"dict_value\") @db.VarChar(100)\n  /// 排序（升序）\n  sort      Int      @default(0)\n  /// 1 启用 / 0 禁用\n  status    Int      @default(1) @db.TinyInt\n  /// 备注\n  remark    String?  @db.VarChar(255)\n  /// 创建时间\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  dictTypeInfo DictType @relation(fields: [dictType], references: [dictType], onDelete: Cascade, onUpdate: Cascade)\n\n  @@index([dictType])\n  @@map(\"sys_dict_item\")\n}\n\n/// 系统参数表\nmodel SysConfig {\n  /// 主键\n  id          BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 参数名称（展示用）\n  configName  String   @map(\"config_name\") @db.VarChar(100)\n  /// 参数键名（业务引用键，创建后不可修改）\n  configKey   String   @unique @map(\"config_key\") @db.VarChar(100)\n  /// 参数键值\n  configValue String   @default(\"\") @map(\"config_value\") @db.VarChar(500)\n  /// 是否内置：1 内置 / 0 自定义\n  systemFlag  Int      @default(0) @map(\"system_flag\") @db.TinyInt\n  /// 备注\n  remark      String?  @db.VarChar(255)\n  /// 创建时间\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"sys_config\")\n}\n\n// use prisma-next\n// ↑ 首行不可删：VS Code 的 Prisma 扩展**按文件**判定是否启用 Prisma 7 语言服务，\n//   缺失会回落到 v6 语义并误报 `Argument \"url\" is missing in data source block \"db\"`。\n//\n// 文件管理\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n/// 文件表\nmodel File {\n  /// 主键\n  id         BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 原始文件名\n  originName String   @map(\"origin_name\") @db.VarChar(255)\n  /// 存储相对路径（扩展名分组/文件名）\n  fileName   String   @map(\"file_name\") @db.VarChar(255)\n  /// 磁盘相对路径\n  filePath   String   @map(\"file_path\") @db.VarChar(500)\n  /// 访问 URL\n  fileUrl    String   @map(\"file_url\") @db.VarChar(500)\n  /// MIME（媒体类型）\n  mimeType   String   @map(\"mime_type\") @db.VarChar(100)\n  /// 字节\n  size       Int      @default(0) @db.Int\n  /// SHA-256 内容哈希（秒传/去重依据）\n  hash       String?  @db.VarChar(64)\n  /// 上传人 id\n  uploaderId BigInt?  @map(\"uploader_id\") @db.BigInt\n  /// 业务类型（归属模块，如 avatar / notice / contract；空 = 无业务归属）\n  bizType    String?  @map(\"biz_type\") @db.VarChar(50)\n  /// 业务主键（关联业务表 id；空 = 未指定）\n  bizId      BigInt?  @map(\"biz_id\") @db.BigInt\n  /// 创建时间\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  @@index([hash])\n  @@index([uploaderId])\n  /// 按业务归属查询（如\"某公告的全部附件\"）\n  @@index([bizType, bizId])\n  @@map(\"sys_file\")\n}\n\n// use prisma-next\n\n// 「短句」游戏化域：经验账本 / 成就定义 / 用户成就。\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n//\n// 三条设计红线（与产品「轻量、隐形、正反馈、不焦虑」理念一致）：\n// 1. **服务端权威**：XP 只由后端按真实事件发放，客户端只上报「发生了什么」，不传经验值；\n// 2. **幂等**：client_xp_log.event_key 唯一，网络重试 / 重复请求不会重复发奖；\n// 3. **只加不减**：没有任何扣减、衰减、断签清空机制——一旦会「失去」，用户就会焦虑然后流失。\n\n/// 经验值账本（一行 = 一次成功发放；event_key 唯一即幂等保证）\nmodel ClientXpLog {\n  /// 主键\n  id        BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 幂等键（answer:{eventId} / favorite:{userId}:{sentenceId} / daily_goal:{userId}:{date} / achievement:{userId}:{code} / backfill:{userId}）\n  eventKey  String   @unique @map(\"event_key\") @db.VarChar(160)\n  /// 用户 id\n  userId    BigInt   @map(\"user_id\") @db.BigInt\n  /// 事件类型：answer_correct_first / answer_correct_review / answer_wrong / favorite / daily_goal / achievement / backfill\n  eventType String   @map(\"event_type\") @db.VarChar(32)\n  /// 本次发放经验值（恒为正：本体系只奖励、不扣减）\n  amount    Int      @db.Int\n  /// 发放时间\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@index([userId, createdAt])\n  @@map(\"client_xp_log\")\n}\n\n/// 成就定义（由种子写入；code 为稳定业务键，勿随意改动）\nmodel Achievement {\n  /// 成就编码（如 streak_7 / collector_50 / night_owl）\n  code        String @id @db.VarChar(64)\n  /// 成就名称\n  name        String @db.VarChar(50)\n  /// 达成条件描述（展示给用户）\n  description String @db.VarChar(200)\n  /// 图标（lucide 图标名，前端直接拼 i-lucide-*）\n  icon        String @db.VarChar(100)\n  /// 分组：persist 坚持 / behavior 行为 / luck 运气\n  category    String @db.VarChar(20)\n  /// 解锁奖励经验值\n  rewardXp    Int    @default(0) @map(\"reward_xp\") @db.Int\n  /// 排序（升序）\n  sort        Int    @default(0)\n\n  @@map(\"achievement\")\n}\n\n/// 用户已解锁成就（userId + code 唯一，重复解锁被唯一键拦截）\nmodel UserAchievement {\n  /// 主键\n  id              BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 用户 id\n  userId          BigInt   @map(\"user_id\") @db.BigInt\n  /// 成就编码（不建外键：成就定义是随发布演进的种子数据，历史解锁记录须保留）\n  achievementCode String   @map(\"achievement_code\") @db.VarChar(64)\n  /// 解锁时间\n  unlockedAt      DateTime @default(now()) @map(\"unlocked_at\")\n\n  @@unique([userId, achievementCode])\n  @@index([userId])\n  @@map(\"user_achievement\")\n}\n\n// use prisma-next\n// ↑ 首行不可删（原因见 base.prisma）。\n//\n// 代码生成器的注入区：gen.writer 会把新模型的 Prisma model 片段插到下方锚点之前。\n// 单独成文件，是为了让「自动生成的 schema 变更」在 diff 里与业务模型分开。\n\n// [GEN-ANCHOR] 代码生成器自动插入位置，请勿删除（gen.writer 会在本行之前插入新模型的 Prisma model 片段）\n\n// use prisma-next\n// ↑ 首行不可删：VS Code 的 Prisma 扩展**按文件**判定是否启用 Prisma 7 语言服务，\n//   缺失会回落到 v6 语义并误报 `Argument \"url\" is missing in data source block \"db\"`。\n//\n// IP 黑名单（自动封禁 / 人工封禁）。公共约定（snake_case 映射 / 注释落库）见 base.prisma。\n/// IP 黑名单（封禁恶意 IP，兜底防批量注册与登录爆破）\nmodel IpBan {\n  /// 主键\n  id         BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 被封禁 IP（IPv4 / IPv6，最长 64）\n  ip         String    @unique @db.VarChar(64)\n  /// 封禁原因\n  reason     String    @db.VarChar(255)\n  /// 封禁类型：auto 系统自动 / manual 人工\n  type       String    @db.VarChar(16)\n  /// 触发来源：register 注册超限 / login 登录爆破 / captcha 验证码绕过 / manual 人工\n  scope      String    @db.VarChar(24)\n  /// 解封时间（null 表示永久封禁）\n  expiresAt  DateTime? @map(\"expires_at\")\n  /// 解封操作时间（非空即已解封）\n  unbannedAt DateTime? @map(\"unbanned_at\")\n  /// 操作人（自动封禁为 system）\n  operator   String?   @db.VarChar(64)\n  /// 创建时间\n  createdAt  DateTime  @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt  DateTime  @updatedAt @map(\"updated_at\")\n\n  @@index([expiresAt])\n  @@map(\"sys_ip_ban\")\n}\n\n// use prisma-next\n// ↑ 首行不可删：VS Code 的 Prisma 扩展**按文件**判定是否启用 Prisma 7 语言服务，\n//   缺失会回落到 v6 语义并误报 `Argument \"url\" is missing in data source block \"db\"`。\n//\n// 日志：登录 / 操作 / HTTP 访问\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n/// 登录日志表\nmodel LoginLog {\n  /// 主键\n  id        BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 登录账号\n  username  String   @db.VarChar(50)\n  /// 客户端 IP\n  ip        String?  @db.VarChar(50)\n  /// User-Agent（用户代理）\n  userAgent String?  @map(\"user_agent\") @db.VarChar(500)\n  /// IP 归属地（ip2region 离线解析：国家 省份 城市 运营商）\n  location  String?  @db.VarChar(100)\n  /// 1 成功 / 0 失败\n  status    Int      @db.TinyInt\n  /// 结果描述\n  message   String?  @db.VarChar(255)\n  /// 登录时间\n  loginAt   DateTime @default(now()) @map(\"login_at\")\n\n  @@index([loginAt])\n  @@map(\"sys_login_log\")\n}\n\n/// 操作日志表\nmodel OperationLog {\n  /// 主键\n  id           BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 操作人 id\n  userId       BigInt?  @map(\"user_id\") @db.BigInt\n  /// 操作人账号\n  username     String?  @db.VarChar(50)\n  /// 模块\n  module       String   @db.VarChar(50)\n  /// 动作\n  action       String   @db.VarChar(50)\n  /// HTTP 方法\n  method       String   @db.VarChar(10)\n  /// 请求 URL\n  url          String   @db.VarChar(255)\n  /// 请求参数（密码脱敏）\n  params       String?  @db.Text\n  /// 变更前数据（JSON 文本；敏感字段已脱敏、超长已截断，仅支持的写操作会写）\n  beforeData   String?  @map(\"before_data\") @db.VarChar(2000)\n  /// 变更后数据（JSON 文本；口径同 before_data）\n  afterData    String?  @map(\"after_data\") @db.VarChar(2000)\n  /// 耗时 ms\n  duration     Int      @default(0)\n  /// 1 成功 / 0 失败\n  result       Int      @db.TinyInt\n  /// 失败信息\n  errorMessage String?  @map(\"error_message\") @db.VarChar(500)\n  /// 客户端 IP\n  ip           String?  @db.VarChar(50)\n  /// IP 归属地（ip2region 离线解析：国家 省份 城市 运营商）\n  location     String?  @db.VarChar(100)\n  /// 创建时间\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  @@index([createdAt])\n  @@map(\"sys_operation_log\")\n}\n\n/// HTTP 访问日志表（页面查询用；操作者为写入时快照，不与 sys_user 建外键）\nmodel HttpLog {\n  /// 主键\n  id         BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 请求完成时间（本地时区 +08:00）\n  time       DateTime @db.DateTime(3)\n  /// HTTP 方法\n  method     String   @db.VarChar(10)\n  /// 请求 URL（含 query）\n  url        String   @db.VarChar(1024)\n  /// HTTP 状态码\n  statusCode Int      @map(\"status_code\") @db.SmallInt\n  /// 耗时 ms\n  duration   Int      @default(0) @db.Int\n  /// 客户端 IP\n  ip         String?  @db.VarChar(64)\n  /// IP 归属地（ip2region 离线解析：国家 省份 城市 运营商）\n  location   String?  @db.VarChar(100)\n  /// User-Agent（用户代理）\n  userAgent  String?  @map(\"user_agent\") @db.VarChar(500)\n  /// 操作用户 id（0 为匿名/未登录）\n  userId     BigInt   @default(0) @map(\"user_id\") @db.BigInt\n  /// 操作账号（快照）\n  username   String?  @db.VarChar(50)\n  /// 所属部门 id 快照（0 为无）\n  deptId     BigInt   @default(0) @map(\"dept_id\") @db.BigInt\n  /// 所属部门名称（快照）\n  deptName   String?  @map(\"dept_name\") @db.VarChar(50)\n  /// 查询参数（已脱敏）\n  query      Json?\n  /// 请求体（已脱敏、截断 2KB）\n  reqBody    String?  @map(\"req_body\") @db.Text\n  /// 响应内容（截断 2KB；二进制为占位）\n  resBody    String?  @map(\"res_body\") @db.Text\n\n  @@index([time])\n  @@index([method])\n  @@index([statusCode])\n  @@index([method, time])\n  // 操作者筛选索引：显式声明，保证每一次全新部署都带 idx_user_id / idx_dept_id\n  @@index([userId])\n  @@index([deptId])\n  // 操作者前缀检索索引（列表按 username startsWith 过滤）\n  @@index([username])\n  @@map(\"sys_http_log\")\n}\n\n/**\n * 站内通知（每个接收人一条记录）。\n * 刻意用「每人一条」而不是「公告一条 + 已读关联表」：\n * 收件人规模可控（后台用户），而按人存能直接支持未读数、逐条已读与个人通知（强制下线、改密提醒），\n * 不需要额外的已读关联表与联表查询。\n */\nmodel Notice {\n  /// 主键\n  id         BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 接收人 id\n  userId     BigInt    @map(\"user_id\") @db.BigInt\n  /// 标题\n  title      String    @db.VarChar(200)\n  /// 正文（纯文本，渲染时按纯文本处理，不接受 HTML）\n  content    String    @db.Text\n  /// 类型：1 系统通知 / 2 公告 / 3 安全提醒\n  noticeType Int       @default(1) @map(\"notice_type\") @db.TinyInt\n  /// 点击跳转的前端路由（空 = 不跳转）\n  link       String?   @db.VarChar(255)\n  /// 0 未读 / 1 已读\n  isRead     Int       @default(0) @map(\"is_read\") @db.TinyInt\n  /// 阅读时间\n  readAt     DateTime? @map(\"read_at\")\n  /// 创建人 id（系统自动通知可为空）\n  createdBy  BigInt?   @map(\"created_by\") @db.BigInt\n  /// 创建时间\n  createdAt  DateTime  @default(now()) @map(\"created_at\")\n\n  /// 个人收件箱列表：按人 + 未读优先 + 时间倒序\n  @@index([userId, isRead, createdAt])\n  @@map(\"sys_notice\")\n}\n\n// use prisma-next\n\n// 「短句」每日句签域：AI 每日生成一张精美句签（可留存的闪卡），用户完成每日目标后获得。\n// 命名取向：对外叫「句签」（贴合「短句」品牌，含「书签/留存」意味），避免「藏品」过于直白。\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n\n/// 每日句签（一天一张，由定时任务 AI 生成；bizDate 唯一即幂等保证）\nmodel DailySentenceCard {\n  /// 主键\n  id            BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 业务日期（YYYY-MM-DD，唯一：一天一张，重复触发幂等跳过）\n  bizDate       String   @unique @map(\"biz_date\") @db.VarChar(10)\n  /// 主题标题（英文，如 Morning Ritual）\n  title         String   @db.VarChar(80)\n  /// 主题标题（中文）\n  titleZh       String   @map(\"title_zh\") @db.VarChar(80)\n  /// 卡面短句（英文）\n  sentenceEn    String   @map(\"sentence_en\") @db.VarChar(200)\n  /// 短句中文释义\n  translationZh String   @map(\"translation_zh\") @db.VarChar(200)\n  /// 寄语（这张卡独有的一句，随文案一起生成；展示在卡背，替代泛用的揭晓文案）\n  blessing      String   @default(\"\") @map(\"blessing\") @db.VarChar(120)\n  /// 生图提示词（运营审核）\n  scenePrompt   String   @map(\"scene_prompt\") @db.VarChar(500)\n  /// 配图文件 id（0 = 未生成，指向 sys_file；故不建外键）\n  imageFileId   BigInt   @default(0) @map(\"image_file_id\") @db.BigInt\n  /// 状态：pending 待生成 / ready 就绪 / failed 失败\n  status        String   @default(\"pending\") @db.VarChar(20)\n  /// 创建时间\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt     DateTime @updatedAt @map(\"updated_at\")\n\n  grants UserSentenceCard[]\n\n  @@index([status, bizDate])\n  @@map(\"daily_sentence_card\")\n}\n\n/// 用户句签（userId + sentenceCardId 唯一，重复领取被唯一键拦截）\nmodel UserSentenceCard {\n  /// 主键\n  id             BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 用户 id\n  userId         BigInt   @map(\"user_id\") @db.BigInt\n  /// 句签 id\n  sentenceCardId BigInt   @map(\"sentence_card_id\") @db.BigInt\n  /// 获得时间\n  obtainedAt     DateTime @default(now()) @map(\"obtained_at\")\n\n  sentenceCard DailySentenceCard @relation(fields: [sentenceCardId], references: [id])\n\n  /// 同一用户同一句签只能获得一次\n  @@unique([userId, sentenceCardId])\n  @@index([userId, obtainedAt])\n  @@map(\"user_sentence_card\")\n}\n\n// use prisma-next\n// ↑ 首行不可删：VS Code 的 Prisma 扩展**按文件**判定是否启用 Prisma 7 语言服务，\n// 缺失会回落到 v6 语义并误报 `Argument \"url\" is missing in data source block \"db\"`。\n//\n// 「短句」业务域：客户端用户 / 场景分类 / 句子题库 / 生成批次 / 答题记录 /\n// 收藏 / 打卡 / AI 调用日志。\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n\n/// 客户端用户（与后台 sys_user 彻底隔离，独立鉴权体系）\nmodel ClientUser {\n  /// 主键\n  id                BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 登录邮箱（唯一）\n  email             String    @unique @db.VarChar(100)\n  /// bcrypt 口令哈希（与后台同策略，见 common/auth/password-policy.ts）\n  password          String    @db.VarChar(100)\n  /// 昵称\n  nickname          String    @db.VarChar(50)\n  /// 头像文件 id（0 = 默认头像，故不建外键）\n  avatarFileId      BigInt    @default(0) @map(\"avatar_file_id\") @db.BigInt\n  /// 出生年月日\n  birthday          DateTime? @db.Date\n  /// 性别：male 男 / female 女 / secret 保密\n  gender            String    @default(\"secret\") @db.VarChar(10)\n  /// 个性签名\n  signature         String?   @db.VarChar(200)\n  /// 个人主页背景句签 id（0 = 未设置，用默认品牌渐变；须为本人已获得的句签）\n  bgCardId          BigInt    @default(0) @map(\"bg_card_id\") @db.BigInt\n  /// 累计经验值（只增不减；由 gamify 服务端按事件发放，幂等账本见 gamify.prisma）\n  xp                Int       @default(0) @db.Int\n  /// 1 启用 / 0 禁用\n  status            Int       @default(1) @db.TinyInt\n  /// 每日学习提醒邮件：1 订阅 / 0 不订阅（用户主动开启才发，即视为同意接收）\n  emailReminder     Int       @default(0) @map(\"email_reminder\") @db.TinyInt\n  /// 最后登录时间\n  lastLoginAt       DateTime? @map(\"last_login_at\")\n  /// 密码最后修改时间（改密后旧 Token 失效判定）\n  passwordChangedAt DateTime? @map(\"password_changed_at\")\n  /// 创建时间\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n\n  // 答题记录 / 收藏 / 打卡不声明 Prisma 关系：与 sys_user.dept_id 的哨兵约定一致，\n  // 一律按 userId 显式查询（见 base.prisma「哨兵值约定」），删除用户时由业务层清理。\n\n  @@index([status])\n  @@map(\"client_user\")\n}\n\n/// 场景分类（题目的主题归类，如「咖啡店点单」「机场通关」）\nmodel SentenceCategory {\n  /// 主键\n  id          BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 分类名称（中文）\n  name        String   @db.VarChar(50)\n  /// 分类名称（英文，卡片副标题用）\n  nameEn      String?  @map(\"name_en\") @db.VarChar(50)\n  /// 图标（bootstrap-icons 类名）\n  icon        String?  @db.VarChar(100)\n  /// 节日题库封面图文件 id（0 = 无封面；仅节日分类使用，指向 sys_file）\n  coverFileId BigInt   @default(0) @map(\"cover_file_id\") @db.BigInt\n  /// 排序（升序）\n  sort        Int      @default(0)\n  /// 1 启用 / 0 禁用\n  status      Int      @default(1) @db.TinyInt\n  /// 创建时间\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  sentences Sentence[]\n\n  @@map(\"sentence_category\")\n}\n\n/// 句子题库（图片由定时任务预生成，status=ready 才下发用户端）\nmodel Sentence {\n  /// 主键\n  id               BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 所属分类\n  categoryId       BigInt    @map(\"category_id\") @db.BigInt\n  /// 难度：1 易 / 2 中 / 3 难\n  difficulty       Int       @default(1) @db.TinyInt\n  /// 英文句子（唯一；批量生成的天然去重键）\n  sentenceEn       String    @unique @db.VarChar(300)\n  /// 其他可接受的英文表达（JSON 数组，最多 5 条；输入模式下用户写出任一条即算对）\n  alternateAnswers String?   @map(\"alternate_answers\") @db.VarChar(1000)\n  /// 中文释义（用户端题干）\n  translationZh    String    @map(\"translation_zh\") @db.VarChar(300)\n  /// IPA 音标（英美合并，如 /ˈkɒfi ˈplez/）\n  ipa              String?   @db.VarChar(200)\n  /// 题目解析（中文：语法点 / 时态语态 / 关键词形与搭配 / 易错点）。\n  /// 答题后**无论对错都展示**，帮用户理解为什么这么写；运营手工创建的题可留空。\n  explanation      String?   @db.VarChar(500)\n  /// 选词模式逐词释义（JSON 对象：词 → 该词在本句中的中文含义，如 {\"coffee\":\"咖啡\"}）。\n  /// 新题在生成流水线「逐词释义」阶段产出；旧题为 null（用户端不显示悬浮提示）。\n  wordMeanings     String?   @map(\"word_meanings\") @db.Text\n  /// 生图提示词（描述「两人对话场景」构图，供运营审核）\n  scenePrompt      String    @map(\"scene_prompt\") @db.VarChar(500)\n  /// 配图文件 id（0 = 未生成，指向 sys_file；故不建外键）\n  imageFileId      BigInt    @default(0) @map(\"image_file_id\") @db.BigInt\n  /// 来源：ai 生成 / manual 运营手工\n  source           String    @default(\"ai\") @db.VarChar(20)\n  /// AI 生成时实际使用的文本通道：agnes / nim（null = 旧数据或手工题，不展示）\n  aiChannel        String?   @map(\"ai_channel\") @db.VarChar(20)\n  /// AI 生成时实际使用的文本模型名（如 agnes-2.5-flash / deepseek-v4.1-flash；null 同上）\n  aiModel          String?   @map(\"ai_model\") @db.VarChar(100)\n  /// 状态：pending_image 待生成 / ready 就绪 / offline 下架\n  status           String    @default(\"pending_image\") @db.VarChar(20)\n  /// 所属生成批次 id（0 = 手工创建）\n  genTaskId        BigInt    @default(0) @map(\"gen_task_id\") @db.BigInt\n  /// 节日题库：所属节日名（如「春节」；普通题为 null）\n  festivalName     String?   @map(\"festival_name\") @db.VarChar(50)\n  /// 节日题库：该次节日的公历日期（YYYY-MM-DD）。同一节日不同年份靠它区分新旧批次\n  festivalDate     String?   @map(\"festival_date\") @db.VarChar(10)\n  /// 退场时间（非空 = 不再出现在练习流；旧节日题库在新一期生成成功后置位）\n  retiredAt        DateTime? @map(\"retired_at\")\n  /// 创建时间\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n\n  category  SentenceCategory   @relation(fields: [categoryId], references: [id])\n  records   SentenceRecord[]\n  favorites SentenceFavorite[]\n  reports   SentenceReport[]\n\n  @@index([status, categoryId])\n  @@index([status, retiredAt])\n  @@index([festivalName, festivalDate])\n  @@index([genTaskId])\n  @@map(\"sentence\")\n}\n\n/// 每日生成批次（一条 = 一天的批量任务）\nmodel SentenceGenTask {\n  /// 主键\n  id              BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 业务日期（YYYY-MM-DD 字符串）。\n  /// 配合 categoryId 组成复合唯一：一天内可同时存在「一个定时全量批次（categoryId=0）」\n  /// 与「多个按分类定向补题批次（categoryId=对应分类 id）」，互不冲突——这正是「填场景」要的能力。\n  bizDate         String    @map(\"biz_date\") @db.VarChar(10)\n  /// 定向补题的分类 id：0 = 定时全量批次（哨兵），其余为对应分类的定向补题批次。\n  /// 仅用于批次维度区分与监控展示，题目最终归属由生题流水线的 targetCategory 决定。\n  categoryId      BigInt    @default(0) @map(\"category_id\") @db.BigInt\n  /// 目标生成数量\n  targetCount     Int       @default(0) @map(\"target_count\")\n  /// 文本已生成数量\n  textDone        Int       @default(0) @map(\"text_done\")\n  /// 图片已生成数量\n  imageDone       Int       @default(0) @map(\"image_done\")\n  /// 失败数量（文本+图片合计）\n  failCount       Int       @default(0) @map(\"fail_count\")\n  /// 状态：pending 待处理 / running 进行中 / success 成功 / failed 失败\n  status          String    @default(\"pending\") @db.VarChar(20)\n  /// 当前阶段：generating 生题 / polishing 优化 / reviewing 审核 / annotating 逐词释义 / imaging 生图 / done 收尾\n  stage           String    @default(\"\") @db.VarChar(20)\n  /// 最近心跳（每完成一批题/一张图更新）：前端据此区分「还在跑」与「卡住了」\n  lastHeartbeatAt DateTime? @map(\"last_heartbeat_at\")\n  /// 触发方式：cron 定时 / manual 手动\n  triggerType     String    @default(\"cron\") @map(\"trigger_type\") @db.VarChar(20)\n  /// 本批是否为节日题库：节日名（null = 普通批次）\n  festivalName    String?   @map(\"festival_name\") @db.VarChar(50)\n  /// 节日日期（YYYY-MM-DD）；与 festivalName 一起标识「哪一年的哪个节日」\n  festivalDate    String?   @map(\"festival_date\") @db.VarChar(10)\n  /// 失败原因摘要（截断到 500 字符）\n  errorMessage    String?   @map(\"error_message\") @db.VarChar(500)\n  /// 开始时间\n  startedAt       DateTime? @map(\"started_at\")\n  /// 结束时间\n  finishedAt      DateTime? @map(\"finished_at\")\n  /// 创建时间\n  createdAt       DateTime  @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt       DateTime  @updatedAt @map(\"updated_at\")\n\n  /// 一天内同一分类最多一个批次（categoryId=0 表示定时全量批次，同样唯一）\n  @@unique([bizDate, categoryId])\n  @@index([categoryId])\n  @@map(\"sentence_gen_task\")\n}\n\n/// 答题记录（一行 = 一次作答；复习池由 isCorrect=0 且 nextReviewAt<=now 派生，不另建表）\nmodel SentenceRecord {\n  /// 主键\n  id           BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 用户 id\n  userId       BigInt    @map(\"user_id\") @db.BigInt\n  /// 句子 id\n  sentenceId   BigInt    @map(\"sentence_id\") @db.BigInt\n  /// 用户当次输入（截断到 300）\n  userAnswer   String    @map(\"user_answer\") @db.VarChar(300)\n  /// 是否正确：1 是 / 0 否\n  isCorrect    Int       @default(0) @map(\"is_correct\") @db.TinyInt\n  /// 作答耗时（毫秒）\n  elapsedMs    Int       @default(0) @map(\"elapsed_ms\") @db.Int\n  /// 间隔重复等级：0=陌生，每答对一次 +1（对应 1/3/7/15/30 天）\n  reviewLevel  Int       @default(0) @map(\"review_level\") @db.TinyInt\n  /// 下次复习时间（null = 未排期，如首次答对安排 +1 天）\n  nextReviewAt DateTime? @map(\"next_review_at\")\n  /// 创建时间\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n\n  sentence Sentence @relation(fields: [sentenceId], references: [id])\n\n  @@index([userId, createdAt])\n  @@index([userId, sentenceId])\n  /// 复习池查询：某用户的错题按到期时间升序\n  @@index([userId, isCorrect, nextReviewAt])\n  @@map(\"sentence_record\")\n}\n\n/// 收藏夹\nmodel SentenceFavorite {\n  /// 主键\n  id         BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 用户 id\n  userId     BigInt   @map(\"user_id\") @db.BigInt\n  /// 句子 id\n  sentenceId BigInt   @map(\"sentence_id\") @db.BigInt\n  /// 创建时间\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  sentence Sentence @relation(fields: [sentenceId], references: [id])\n\n  /// 同一用户对同一句子只能收藏一次\n  @@unique([userId, sentenceId])\n  @@map(\"sentence_favorite\")\n}\n\n/// 题目举报/反馈（用户端「举报」按钮提交，供运营核查处理）\nmodel SentenceReport {\n  /// 主键\n  id          BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 举报人用户 id（client_user）\n  userId      BigInt    @map(\"user_id\") @db.BigInt\n  /// 被举报句子 id\n  sentenceId  BigInt    @map(\"sentence_id\") @db.BigInt\n  /// 举报类型：wrong 题目/翻译有误 / inappropriate 内容不适当 / image 图片不雅 / other 其他\n  reason      String    @db.VarChar(20)\n  /// 补充描述（可选）\n  description String?   @db.VarChar(500)\n  /// 处理状态：pending 待处理 / resolved 已处理 / dismissed 已驳回\n  status      String    @default(\"pending\") @db.VarChar(20)\n  /// 处理备注（运营填写）\n  handleNote  String?   @map(\"handle_note\") @db.VarChar(500)\n  /// 处理时间\n  handledAt   DateTime? @map(\"handled_at\")\n  /// 创建时间\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n\n  sentence Sentence @relation(fields: [sentenceId], references: [id])\n\n  @@index([status, createdAt])\n  @@index([sentenceId])\n  @@index([userId, createdAt])\n  @@map(\"sentence_report\")\n}\n\n/// 每日打卡（一行 = 一个用户一天的完成记录）\nmodel UserCheckin {\n  /// 主键\n  id           BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 用户 id\n  userId       BigInt   @map(\"user_id\") @db.BigInt\n  /// 打卡日期（YYYY-MM-DD 字符串）\n  checkinDate  String   @map(\"checkin_date\") @db.VarChar(10)\n  /// 当日完成题数\n  doneCount    Int      @default(0) @map(\"done_count\")\n  /// 当日目标题数\n  goalCount    Int      @default(0) @map(\"goal_count\")\n  /// 连续打卡天数（截止本次）\n  streak       Int      @default(1) @db.TinyInt\n  /// 打卡海报文件 id（0 = 未生成；海报在前端 html2canvas 生成，一般留空）\n  posterFileId BigInt   @default(0) @map(\"poster_file_id\") @db.BigInt\n  /// 创建时间\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  /// 同一用户同一天只允许一条打卡\n  @@unique([userId, checkinDate])\n  @@map(\"user_checkin\")\n}\n\n/// AI 调用日志（生题/生图/造句/词根，计费与排障依据）\nmodel AiCallLog {\n  /// 主键\n  id               BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 调用类型：sentence_gen 生题 / sentence_polish 优化 / sentence_review 审核 / word_meanings 逐词释义 / sentence_card_gen 句签 / image_gen 生图 / expand 造句 / word_root 词根\n  type             String   @db.VarChar(20)\n  /// 提供方（如 nvidia / agnes-ai）\n  provider         String   @db.VarChar(50)\n  /// 模型标识（如 deepseek-v4.1-flash / agnes-image-2.5-flash）\n  model            String   @db.VarChar(100)\n  /// 关联业务 id（批次/句子/用户，按类型解释）\n  bizId            BigInt   @default(0) @map(\"biz_id\") @db.BigInt\n  /// 输入 token 数（生题类）\n  promptTokens     Int      @default(0) @map(\"prompt_tokens\")\n  /// 输出 token 数\n  completionTokens Int      @default(0) @map(\"completion_tokens\")\n  /// 耗时（毫秒）\n  latencyMs        Int      @default(0) @map(\"latency_ms\")\n  /// 状态：success / failed\n  status           String   @default(\"success\") @db.VarChar(20)\n  /// 错误摘要（截断到 500 字符）\n  errorMessage     String?  @map(\"error_message\") @db.VarChar(500)\n  /// 创建时间\n  createdAt        DateTime @default(now()) @map(\"created_at\")\n\n  @@index([type, createdAt])\n  @@index([bizId])\n  @@map(\"ai_call_log\")\n}\n\n// use prisma-next\n\n/// 情景闯关进度（一行 = 用户在某场景关卡上的累计进度）。\n///\n/// **为什么不从 sentence_record 派生**：答题记录默认只保留 30 天\n/// （每日 00:20 清理 `< now-30d`），派生口径会让用户一个月后「通关进度倒退」，\n/// 关卡也会重新上锁。本表只增不减，是解锁与通关奖励的权威依据。\n///\n/// 与答题/打卡/句签同口径，刻意不与 client_user 建 Prisma 关系，按 userId 显式查询。\nmodel StudyStageProgress {\n  /// 主键\n  id           BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 用户 id（client_user）\n  userId       BigInt    @map(\"user_id\") @db.BigInt\n  /// 场景分类 id（sentence_category）：关卡 = 场景\n  categoryId   BigInt    @map(\"category_id\") @db.BigInt\n  /// 累计答对数（只增不减，用于通关判定与进度展示）\n  correctCount Int       @default(0) @map(\"correct_count\") @db.Int\n  /// 累计作答数（含答错）\n  answerCount  Int       @default(0) @map(\"answer_count\") @db.Int\n  /// 首次通关时间（null = 未通关；只写一次，后续答对不改写）\n  clearedAt    DateTime? @map(\"cleared_at\")\n  /// 创建时间\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n\n  /// 一个用户在一个场景只有一行\n  @@unique([userId, categoryId])\n  @@index([userId])\n  @@map(\"study_stage_progress\")\n}\n\n// use prisma-next\n\n/// 弱连接学习小队：系统按「近 7 天练习节奏」自动匹配陌生人，队员互不加好友，\n/// 只互相看到今日打卡状态与连续天数（无聊天、无 UGC，规避内容审核成本）。\nmodel StudyTeam {\n  /// 主键\n  id           BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 小队名（系统生成，如「晨光小队」）\n  name         String   @db.VarChar(50)\n  /// 状态：active 进行中 / dissolved 已解散（成员退空后置位）\n  status       String   @default(\"active\") @db.VarChar(20)\n  /// 匹配分桶：近 7 天答题量档位（0~4），同桶才能匹配，保证节奏相近\n  bucket       Int      @default(0) @db.Int\n  /// 全员打卡连续天数\n  streak       Int      @default(0) @db.Int\n  /// 最近一次「全员完成」日期 YYYY-MM-DD；断签判定用\n  lastFullDate String?  @map(\"last_full_date\") @db.VarChar(10)\n  /// 创建时间\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  members StudyTeamMember[]\n\n  @@index([status, bucket])\n  @@map(\"study_team\")\n}\n\n/// 小队成员：一个用户同时只能在一个小队（换队先删旧记录）。\n/// 刻意不与 client_user 建 Prisma 关系，与答题/打卡/句签同口径按 userId 显式查询。\nmodel StudyTeamMember {\n  /// 主键\n  id         BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 小队 id\n  teamId     BigInt   @map(\"team_id\") @db.BigInt\n  /// 用户 id（client_user）\n  userId     BigInt   @map(\"user_id\") @db.BigInt\n  /// 加入日期 YYYY-MM-DD\n  joinedDate String   @map(\"joined_date\") @db.VarChar(10)\n  /// 创建时间\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  team StudyTeam @relation(fields: [teamId], references: [id], onDelete: Cascade)\n\n  @@unique([userId])\n  @@index([teamId])\n  @@map(\"study_team_member\")\n}\n\n// use prisma-next\n// ↑ 首行不可删：VS Code 的 Prisma 扩展**按文件**判定是否启用 Prisma 7 语言服务，\n//   缺失会回落到 v6 语义并误报 `Argument \"url\" is missing in data source block \"db\"`。\n//\n// 系统与权限：用户 / 角色 / 菜单 / 部门，以及三张关联表\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n/// 用户表\nmodel User {\n  /// 主键\n  id                BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 登录账号\n  username          String    @unique @db.VarChar(50)\n  /// bcrypt 哈希\n  password          String    @db.VarChar(100)\n  /// 昵称\n  nickname          String    @default(\"\") @db.VarChar(50)\n  /// 头像 URL\n  avatar            String?   @db.VarChar(255)\n  /// 邮箱\n  email             String?   @db.VarChar(100)\n  /// 手机号\n  phone             String?   @db.VarChar(20)\n  /// 性别（字典 sys_user_sex），字符串存储以便字典值扩展\n  gender            String?   @db.VarChar(20)\n  /// 1 启用 / 0 禁用\n  status            Int       @default(1) @db.TinyInt\n  /// 最后登录时间\n  lastLoginAt       DateTime? @map(\"last_login_at\")\n  /// 密码最后修改时间\n  passwordChangedAt DateTime? @map(\"password_changed_at\")\n  /// 备注\n  remark            String?   @db.VarChar(255)\n  /// 部门 id（0 表示未分配，故不建外键、也不声明 Prisma 关系）\n  deptId            BigInt    @default(0) @map(\"dept_id\") @db.BigInt\n  /// 创建时间\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n\n  /// 经中间表 UserRole 的直接角色关联。\n  /// ⚠️ 必须走显式中间表 `sys_user_role`（`userRoles.role`），**不要**改回隐式多对多：\n  ///    隐式 `Role[]` 关系会让 Prisma 另建一张 `_userroles` 表，与业务读写的 `sys_user_role`\n  ///    不互通——表现为角色恒为空、权限码为空、所有带权限码的接口 403、前端菜单树为空。\n  userRoles UserRole[]\n\n  /// 用户级额外权限覆盖（在角色权限之上单独对该用户「额外授予 / 额外撤销」，见 UserMenu 模型）\n  userMenus UserMenu[]\n\n  @@index([deptId])\n  @@map(\"sys_user\")\n}\n\n/// 角色表\nmodel Role {\n  /// 主键\n  id        BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 角色名称\n  roleName  String   @map(\"role_name\") @db.VarChar(50)\n  /// 角色编码\n  roleCode  String   @unique @map(\"role_code\") @db.VarChar(50)\n  /// 排序\n  sort      Int      @default(0)\n  /// 1 启用 / 0 禁用\n  status    Int      @default(1) @db.TinyInt\n  /// 数据权限范围：1 全部 / 2 自定义部门 / 3 本部门及以下 / 4 仅本人\n  dataScope Int      @default(1) @map(\"data_scope\") @db.TinyInt\n  /// 备注\n  remark    String?  @db.VarChar(255)\n  /// 创建时间\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  /// 同样只走显式中间表（见 User 模型上的说明，勿改回隐式多对多）\n  userRoles UserRole[]\n  roleMenus RoleMenu[]\n  roleDepts RoleDept[]\n\n  @@map(\"sys_role\")\n}\n\n/// 菜单权限表\nmodel Menu {\n  /// 主键\n  id         BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 父级 id（0 表示根节点，故不建外键、也不声明 Prisma 自关联）\n  parentId   BigInt   @default(0) @map(\"parent_id\") @db.BigInt\n  /// 菜单名称\n  menuName   String   @map(\"menu_name\") @db.VarChar(50)\n  /// M 目录 / C 菜单 / F 按钮\n  menuType   String   @map(\"menu_type\") @db.Char(1)\n  /// 路由路径\n  path       String?  @db.VarChar(200)\n  /// 组件路径\n  component  String?  @db.VarChar(255)\n  /// 图标\n  icon       String?  @db.VarChar(100)\n  /// 权限标识\n  permission String?  @db.VarChar(100)\n  /// 排序\n  sort       Int      @default(0)\n  /// 1 显示 / 0 隐藏\n  visible    Int      @default(1) @db.TinyInt\n  /// 1 启用 / 0 禁用\n  status     Int      @default(1) @db.TinyInt\n  /// 重定向\n  redirect   String?  @db.VarChar(255)\n  /// 1 缓存 / 0 不缓存\n  keepAlive  Int      @default(0) @map(\"keep_alive\") @db.TinyInt\n  /// 创建时间\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  roleMenus RoleMenu[]\n  userMenus UserMenu[]\n\n  @@index([parentId])\n  @@map(\"sys_menu\")\n}\n\n/// 部门表\nmodel Dept {\n  /// 主键\n  id        BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 父级 id（0 表示顶级，故不建外键、也不声明 Prisma 自关联）\n  parentId  BigInt   @default(0) @map(\"parent_id\") @db.BigInt\n  /// 类型：1 部门 / 2 岗位（岗位为叶子节点，不能再挂下级）\n  deptType  Int      @default(1) @map(\"dept_type\") @db.TinyInt\n  /// 部门名称\n  deptName  String   @map(\"dept_name\") @db.VarChar(50)\n  /// 排序\n  sort      Int      @default(0)\n  /// 1 启用 / 0 禁用\n  status    Int      @default(1) @db.TinyInt\n  /// 部门负责人\n  leader    String?  @db.VarChar(20)\n  /// 联系电话\n  phone     String?  @db.VarChar(20)\n  /// 邮箱\n  email     String?  @db.VarChar(100)\n  /// 创建时间\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  roleDepts RoleDept[]\n\n  @@index([parentId])\n  @@map(\"sys_dept\")\n}\n\n/// 用户角色关联表\nmodel UserRole {\n  /// 主键\n  id     BigInt @id @default(autoincrement()) @db.BigInt\n  /// 用户 id\n  userId BigInt @map(\"user_id\") @db.BigInt\n  /// 角色 id\n  roleId BigInt @map(\"role_id\") @db.BigInt\n\n  user User @relation(fields: [userId], references: [id])\n  role Role @relation(fields: [roleId], references: [id])\n\n  @@unique([userId, roleId])\n  @@index([roleId])\n  @@map(\"sys_user_role\")\n}\n\n/// 角色菜单关联表\nmodel RoleMenu {\n  /// 主键\n  id     BigInt @id @default(autoincrement()) @db.BigInt\n  /// 角色 id\n  roleId BigInt @map(\"role_id\") @db.BigInt\n  /// 菜单 id\n  menuId BigInt @map(\"menu_id\") @db.BigInt\n\n  role Role @relation(fields: [roleId], references: [id])\n  menu Menu @relation(fields: [menuId], references: [id])\n\n  @@unique([roleId, menuId])\n  @@index([menuId])\n  @@map(\"sys_role_menu\")\n}\n\n/// 角色数据权限部门关联表（承载 data_scope=2 的自定义部门集合）\nmodel RoleDept {\n  /// 主键\n  id     BigInt @id @default(autoincrement()) @db.BigInt\n  /// 角色 id\n  roleId BigInt @map(\"role_id\") @db.BigInt\n  /// 部门 id\n  deptId BigInt @map(\"dept_id\") @db.BigInt\n\n  role Role @relation(fields: [roleId], references: [id])\n  dept Dept @relation(fields: [deptId], references: [id])\n\n  @@unique([roleId, deptId])\n  @@index([deptId])\n  @@map(\"sys_role_dept\")\n}\n\n/// 用户级额外权限覆盖表\n/// 语义：某个用户的有效菜单集合 =（其所有角色的菜单并集 ∪ type=1 的菜单）− type=2 的菜单。\n/// 用于「只给某一个人加点权限 / 收掉一点权限」，而不必改动角色（改角色会波及该角色下所有人）。\n/// 该表**不参与种子重建**（角色授权每次种子会重建，但用户级覆盖需长期保留）。\nmodel UserMenu {\n  /// 主键\n  id     BigInt @id @default(autoincrement()) @db.BigInt\n  /// 用户 id\n  userId BigInt @map(\"user_id\") @db.BigInt\n  /// 菜单 id\n  menuId BigInt @map(\"menu_id\") @db.BigInt\n  /// 覆盖类型：1 额外授予（grant）/ 2 额外撤销（revoke）\n  type   Int    @db.TinyInt\n\n  user User @relation(fields: [userId], references: [id])\n  menu Menu @relation(fields: [menuId], references: [id])\n\n  @@unique([userId, menuId])\n  @@index([menuId])\n  @@map(\"sys_user_menu\")\n}\n\n// use prisma-next\n// ↑ 首行不可删：VS Code 的 Prisma 扩展**按文件**判定是否启用 Prisma 7 语言服务，\n//   缺失会回落到 v6 语义并误报 `Argument \"url\" is missing in data source block \"db\"`。\n//\n// 定时任务：执行记录\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n\n/// 定时任务执行记录表\n/// 每次执行（自动触发或手动触发）落一条记录，是「定时任务管理」页的历史轨迹来源。\n/// 刻意只记录**执行结果**而不记录任务定义（cron 表达式、启停状态）：\n/// 任务定义在代码里（见 src/modules/task/task.service.ts），是唯一事实来源；\n/// 若把定义也存进库，就会出现「库里的 cron」与「代码里的 cron」两套口径，\n/// 改动其中一处就会漂移——这正是本项目在角色授权上踩过的坑。\nmodel TaskLog {\n  /// 主键\n  id           BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 任务标识（代码中的任务 key，如 log-archive）\n  taskName     String    @map(\"task_name\") @db.VarChar(64)\n  /// 任务名称（快照：任务改名后历史记录仍保留当时的名称）\n  taskTitle    String    @map(\"task_title\") @db.VarChar(100)\n  /// 触发方式：1 自动（cron）/ 2 手动（管理端点击「立即执行」）\n  triggerType  Int       @map(\"trigger_type\") @db.TinyInt\n  /// 执行状态：0 执行中 / 1 成功 / 2 失败\n  status       Int       @db.TinyInt\n  /// 开始时间\n  startedAt    DateTime  @map(\"started_at\")\n  /// 结束时间（执行中尚未写入）\n  finishedAt   DateTime? @map(\"finished_at\")\n  /// 耗时（毫秒）\n  duration     Int       @default(0)\n  /// 失败原因（成功时为空）\n  errorMessage String?   @map(\"error_message\") @db.VarChar(1000)\n  /// 手动触发人账号（自动触发为空）\n  operator     String?   @db.VarChar(50)\n  /// 记录创建时间\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n\n  // 按任务 + 时间倒序查历史（任务管理页的「执行记录」抽屉）\n  @@index([taskName, startedAt])\n  @@map(\"sys_task_log\")\n}\n\n// use prisma-next\n\n// 「短句」词根词典：用户搜索的词根解析缓存 + 每日批量入库。\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n\n/// 单词词根解析（AI 生成，按单词唯一：命中缓存直接返回，未命中再实时解析）\nmodel WordRoot {\n  /// 主键\n  id          BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 单词（统一小写，唯一业务键）\n  word        String   @unique @db.VarChar(64)\n  /// 音标（如 /ˌʌnəˈvɔɪdəbl/）\n  phonetic    String?  @db.VarChar(120)\n  /// 中文释义（含词性）\n  meaning     String?  @db.VarChar(300)\n  /// 结构化解析：{ parts: [{type,text,meaning}], explanation, related[] }\n  analysis    Json     @db.Json\n  /// 来源：ai 实时解析 / daily 每日批量\n  source      String   @default(\"ai\") @db.VarChar(20)\n  /// 被搜索次数（热度排序用）\n  searchCount Int      @default(0) @map(\"search_count\") @db.Int\n  /// 创建时间\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([searchCount])\n  @@map(\"word_root\")\n}\n",
